import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"]
    cdc_events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts
    if watermark is not None and len(watermark) > 0 and "high_ts" in watermark.columns:
        non_null = watermark["high_ts"].dropna()
        high_ts = non_null.max() if len(non_null) > 0 else pd.Timestamp.min
    else:
        high_ts = pd.Timestamp.min

    # Build initial state from target_snapshot
    state = {}
    for row in target_snapshot.itertuples(index=False):
        state[row.item_id] = {
            "qty": float(row.qty_on_hand),
            "ts": row.last_event_ts,
        }

    # Filter events strictly after the watermark
    events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort deterministically: by event_ts then event_seq (ascending)
    events = events.sort_values(
        by=["event_ts", "event_seq"], kind="mergesort"
    )

    for row in events.itertuples(index=False):
        item_id = row.item_id
        op = row.op
        qty = row.qty
        ts = row.event_ts

        if op == "D":
            if item_id in state:
                del state[item_id]
        elif op == "R":
            if item_id in state:
                state[item_id]["qty"] = state[item_id]["qty"] + qty
                state[item_id]["ts"] = ts
            else:
                state[item_id] = {"qty": 0.0 + qty, "ts": ts}
        elif op == "A":
            state[item_id] = {"qty": qty, "ts": ts}
        else:
            # Unknown op codes are ignored (defensive, not expected per spec)
            pass

    if state:
        out_rows = [
            {"item_id": item_id, "qty_on_hand": v["qty"], "last_event_ts": v["ts"]}
            for item_id, v in state.items()
        ]
        new_snapshot = pd.DataFrame(out_rows, columns=["item_id", "qty_on_hand", "last_event_ts"])
        new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
        new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
        new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"]).astype("datetime64[us]")
    else:
        new_snapshot = pd.DataFrame(
            {
                "item_id": pd.Series(dtype="int64"),
                "qty_on_hand": pd.Series(dtype="float64"),
                "last_event_ts": pd.Series(dtype="datetime64[us]"),
            }
        )

    return {"new_snapshot": new_snapshot}
